void cmul_q15(const int16_t *a, const int16_t *b, int16_t *y, size_t n) {
    size_t i = 0;
    for (; i + 7 < n; i += 8) {
        // Load 8 complex samples (16 elements) from a and b
        vint16m1_t va = vle16_v_i16m1(&a[i], 8);
        vint16m1_t vb = vle16_v_i16m1(&b[i], 8);

        // Extract real and imaginary parts
        vint16m1_t ar = vslidedown_vx_i16m1(va, 0, 8);  // a[2k] real parts
        vint16m1_t ai = vslidedown_vx_i16m1(va, 1, 8);  // a[2k+1] imag parts
        vint16m1_t br = vslidedown_vx_i16m1(vb, 0, 8);  // b[2k] real parts
        vint16m1_t bi = vslidedown_vx_i16m1(vb, 1, 8);  // b[2k+1] imag parts

        // Compute complex multiplication: (ar + j*ai) * (br + j*bi)
        // re = ar*br - ai*bi
        vint32m2_t ar_br = vmul_vv_i32m2(ar, br, 8);
        vint32m2_t ai_bi = vmul_vv_i32m2(ai, bi, 8);
        vint32m2_t re = vsub_vv_i32m2(ar_br, ai_bi, 8);

        // im = ar*bi + ai*br
        vint32m2_t ar_bi = vmul_vv_i32m2(ar, bi, 8);
        vint32m2_t ai_br = vmul_vv_i32m2(ai, br, 8);
        vint32m2_t im = vadd_vv_i32m2(ar_bi, ai_br, 8);

        // Scale and saturate: (value + 16384) >> 15
        vint32m2_t const_16384 = vmv_v_x_i32m2(16384, 8);
        vint32m2_t re_shifted = vsra_vx_i32m2(vadd_vv_i32m2(re, const_16384, 8), 15, 8);
        vint32m2_t im_shifted = vsra_vx_i32m2(vadd_vv_i32m2(im, const_16384, 8), 15, 8);

        // Saturate to int16
        vint16m1_t y_re = vssub_vs_i16m1(re_shifted, 0, 8);
        vint16m1_t y_im = vssub_vs_i16m1(im_shifted, 0, 8);

        // Interleave real and imaginary parts back
        vint16m1_t vy = vslideup_vx_i16m1(y_im, y_re, 0, 8);

        // Store result
        vse16_v_i16m1(&y[i], vy, 8);
    }

    // Handle remaining elements
    for (; i < n; i += 2) {
        int16_t ar = a[i];
        int16_t ai = a[i+1];
        int16_t br = b[i];
        int16_t bi = b[i+1];

        // Compute complex multiplication: (ar + j*ai) * (br + j*bi)
        // re = ar*br - ai*bi
        int32_t re = (int32_t)ar * br - (int32_t)ai * bi;
        // im = ar*bi + ai*br
        int32_t im = (int32_t)ar * bi + (int32_t)ai * br;

        // Scale and saturate: (value + 16384) >> 15
        y[i] = (int16_t)((re + 16384) >> 15);
        y[i+1] = (int16_t)((im + 16384) >> 15);
    }
}

