        // Sum training cells after the cell
        for (size_t j = 0; j < train; j++) {
            S += p[i + guard + 1 + j];
        }

        // Calculate threshold
        int64_t threshold = (int64_t)alpha * S;
        int64_t product = (int64_t)p[i] * total_train;

        // Compare and set detection
        if (product > threshold) {
            det[i] = 1;
        }
    }
}

