void cfar_ca_i32(const int32_t *p, uint8_t *det, size_t n, size_t guard, size_t train, int32_t alpha) {
    // Initialize all detections to 0
    for (size_t i = 0; i < n; i++) {
        det[i] = 0;
    }

    // Early return if not enough elements for processing
    if (n < 2 * guard + 2 * train) return;

    size_t w = guard + train;
    size_t total_train = 2 * train;

    // Process valid cells where 2*train training cells are available
    for (size_t i = w; i < n - w; i++) {
        int64_t S = 0;

        // Sum training cells before guard region
        const int32_t *p_start = p + i - train - guard;
        const int32_t *p_end = p + i - guard;

        size_t vl = p_end - p_start;
        if (vl > 0) {
