        }

        // Sum training cells after guard region
        p_start = p + i + guard + 1;
        p_end = p + i + guard + 1 + train;

        vl = p_end - p_start;
        if (vl > 0) {
            vint32m1_t v_p = __riscv_vle32_v_i32m1(p_start, vl);
            vint64m2_t v_sum = __riscv_vwredsum_vs_i32m1_i64m2(v_p, __riscv_vmv_v_x_i64m2(0, vl), vl);
            S += __riscv_vmv_x_s_i64m2_i64(v_sum);
        }

        // Compute threshold comparison
        int64_t p_val = (int64_t)p[i];
        int64_t alpha_S = (int64_t)alpha * S;
        int64_t two_train = (int64_t)total_train;
        int64_t p_times_two_train = p_val * two_train;

