#include <stdint.h>
#include <stddef.h>
#include <math.h>

void dc_remove_f32(const float *x, float *y, size_t n) {
    if (n == 0) return;

    // Calculate sum using vector reduction
    size_t vl = vsetvl_e32m1(n);
    vfloat32m1_t vsum = vfmv_v_f_f32m1(0.0f, vl);
    size_t i = 0;

    // Vectorized summation
    for (; i < n; i += vl) {
        vl = vsetvl_e32m1(n - i);
        vfloat32m1_t vx = vle32_v_f32m1(&x[i], vl);
        vsum = vfadd_vv_f32m1(vsum, vx, vl);
    }

    // Reduce sum to scalar
    float sum = vfmv_f_s_f32m1_f32(vsum);
    float mean = sum / n;

    // Subtract mean from each element
    vl = vsetvl_e32m1(n);
    i = 0;

    for (; i < n; i += vl) {
        vl = vsetvl_e32m1(n - i);
        vfloat32m1_t vx = vle32_v_f32m1(&x[i], vl);
        vfloat32m1_t vmean = vfmv_v_f_f32m1(mean, vl);
        vfloat32m1_t vy = vfsub_vv_f32m1(vx, vmean, vl);
        vse32_v_f32m1(&y[i], vy, vl);
    }
}

