#include "xdsp.h"

void cmul_q15(const int16_t *a, const int16_t *b, int16_t *y, size_t n) {
    size_t i;

    // Process pairs of complex samples (2 samples per iteration)
    for (i = 0; i < n; i += 2) {
        // Load 2 pairs of complex numbers
        v4int16 va = vld4s((const int16_t *)&a[i*2]);
        v4int16 vb = vld4s((const int16_t *)&b[i*2]);

        // Extract real and imaginary parts
        v2int16 ar = vget_low_s16(va);  // [ar0, ar1]
        v2int16 ai = vget_high_s16(va); // [ai0, ai1]
        v2int16 br = vget_low_s16(vb);  // [br0, br1]
        v2int16 bi = vget_high_s16(vb); // [bi0, bi1]

        // Compute real part: re = ar*br - ai*bi
        v2int32 re_lo = vmull_s16(ar, br);  // ar0*br0, ar1*br1
        v2int32 re_hi = vmull_s16(ai, bi);  // ai0*bi0, ai1*bi1
        v2int32 re = vsubq_s32(re_lo, re_hi);  // (ar0*br0 - ai0*bi0), (ar1*br1 - ai1*bi1)

        // Compute imaginary part: im = ar*bi + ai*br
        v2int32 im_lo = vmull_s16(ar, bi);  // ar0*bi0, ar1*bi1
        v2int32 im_hi = vmull_s16(ai, br);  // ai0*br0, ai1*br1
        v2int32 im = vaddq_s32(im_lo, im_hi);  // (ar0*bi0 + ai0*br0), (ar1*bi1 + ai1*br1)

        // Saturate and shift: result = saturate_int16((val + 16384) >> 15)
        v2int32 re_shifted = vshrq_n_s32(vaddq_s32(re, vdupq_n_s32(16384)), 15);
        v2int32 im_shifted = vshrq_n_s32(vaddq_s32(im, vdupq_n_s32(16384)), 15);

        // Saturate to int16
        v2int16 re_sat = vqmovn_s32(re_shifted);
        v2int16 im_sat = vqmovn_s32(im_shifted);

        // Pack real and imaginary parts back into interleaved format
        v4int16 result = vcombine_s16(re_sat, im_sat);

        // Store the result
        vst4s((int16_t *)&y[i*2], result);
    }
}

