size_t argmax_abs_q15(const int16_t *x, size_t n) {
    if (n == 1) {
        return 0;
    }

    size_t idx = 0;
    int16_t max_mag = (x[0] == INT16_MIN) ? 32767 : abs(x[0]);

    // Process pairs of elements when possible
    size_t i = 1;
    for (; i + 1 < n; i += 2) {
        int16x2_t vec_x = vld1_s16(&x[i]);
        uint16x2_t vec_abs = vabs_s16(vec_x);

        // Clamp to 32767
        uint16x2_t vec_clamped = vmin_u16(vec_abs, vdup_n_u16(32767));

        // Find maximum in pair
        uint16x2_t max_pair = vpmax_u16(vec_clamped, vec_clamped);
        int16_t pair_max = (int16_t)vget_lane_u16(max_pair, 0);

        if (pair_max > max_mag) {
            max_mag = pair_max;
            idx = i + ((x[i] == -32768 || x[i] == 32767) ? 0 : 
                      (abs(x[i]) >= abs(x[i+1]) ? 0 : 1));
        } else if (pair_max == max_mag) {
            // Tie-breaking: keep smaller index
            if (x[i] == -32768 || x[i] == 32767) {
                // This element is at maximum magnitude
                idx = i;
            } else if (x[i+1] == -32768 || x[i+1] == 32767) {
                // Next element is at maximum magnitude
                idx = i + 1;
            }
        }
    }

    // Handle remaining elements
    for (; i < n; i++) {
        int16_t mag = (x[i] == INT16_MIN) ? 32767 : abs(x[i]);
        if (mag > max_mag) {
            max_mag = mag;
            idx = i;
        }
    }

    return idx;
}

