void cmul_q15(const int16_t *a, const int16_t *b, int16_t *y, size_t n) {
    for (size_t vl; n > 0; n -= vl, a += 2*vl, b += 2*vl, y += 2*vl) {
        vl = xd_hlen(n / 2);
        if (vl == 0) break;

        xd_h ar = xd_hload(a, vl);
        xd_h ai = xd_hload(a + vl, vl);
        xd_h br = xd_hload(b, vl);
        xd_h bi = xd_hload(b + vl, vl);

        // Compute re = ar*br - ai*bi
        xd_w re = xd_wmul(ar, br, vl);
        re = xd_wsub(re, xd_wmul(ai, bi, vl), vl);

        // Compute im = ar*bi + ai*br
        xd_w im = xd_wmul(ar, bi, vl);
        im = xd_wadd(im, xd_wmul(ai, br, vl), vl);

        // Convert back to Q15 with rounding and saturation
        xd_h yre = xd_wnarrow(re, 15, vl);
        xd_h yim = xd_wnarrow(im, 15, vl);

        xd_hstore(y, yre, vl);
        xd_hstore(y + vl, yim, vl);
    }
}

