size_t argmax_abs_q15(const int16_t *x, size_t n) {
    xd_w max_acc = xd_wdup(0, xd_hmaxlen());
    xd_h idx_acc = xd_hdup(0, xd_hlen(n));
    xd_w idx_w = xd_wdup(0, xd_hmaxlen());
