        // Find maximum in current chunk
        xd_hmask mask = xd_wgtx(w_abs, max_val, vl);
        if (xd_hcount(mask, vl) > 0) {
            xd_h new_max = xd_hredmax(abs_v, vl);
            int16_t new_max_val = xd_hredmax(abs_v, vl);

            // Update global maximum and index
            if (new_max_val > max_val) {
                max_val = new_max_val;
                max_idx = 0;

                // Find the first occurrence of max_val
                size_t first_pos = xd_hfirst(mask, vl);
                if (first_pos >= 0) {
                    max_idx = first_pos;
                }
            } else if (new_max_val == max_val) {
                // Tie-breaking: keep smallest index
                size_t first_pos = xd_hfirst(mask, vl);
                if (first_pos >= 0 && first_pos < max_idx) {
                    max_idx = first_pos;
                }
            }
        }

        // Update accumulator with current values for next iteration
        max_acc = xd_wmac(max_acc, abs_v, abs_v, vl);
    }

    return max_idx;
}

