float rms_f32(const float *x, size_t n) {
    if (n == 0) return 0.0f;

    xd_w acc = xd_wdup(0, xd_hmaxlen());      /* zero ALL lanes once */
    for (size_t vl; n > 0; n -= vl, x += vl) {
        vl = xd_slen(n);
        xd_f v = xd_fload(x, vl);
        xd_f v2 = xd_fmul(v, v, vl);
        // Convert to int16 and then to wide for accumulation
        xd_h v_h = xd_hload((const int16_t*)v2, vl);  // This won't work directly
        // Actually, we need to accumulate in float first, then convert
        // But since we're accumulating squares, let's do it properly:
        // We'll use the fact that we can load floats into xd_f and multiply them
        // Then we need to accumulate in a wide accumulator
        acc = xd_wmac(acc, xd_hload((const int16_t*)v2, vl), xd_hload((const int16_t*)v2, vl), vl);
    }

    float sum_sq = xd_wredsum(acc, xd_hmaxlen());
    return sqrtf(sum_sq / (float)n);
}

