    xd_h max_idx = xd_hzero(xd_hlen(1));
    xd_h idx = xd_hzero(xd_hlen(1));
    xd_h x_vec;
    xd_hmask mask;

    // Process elements in chunks of XD_HLANES
    for (size_t i = 0; i < n; i += vl) {
        vl = xd_hlen(n - i);

        // Load vector
        x_vec = xd_hload(x + i, vl);

        // Compute absolute values with saturation
        xd_h abs_x = xd_habssat(x_vec, vl);

        // Update maximum and index
        mask = xd_hgt(abs_x, max_mag, vl);
        max_mag = xd_hsel(mask, abs_x, max_mag, vl);
        max_idx = xd_hsel(mask, idx, max_idx, vl);

        // Increment index vector
        idx = xd_hadd(idx, xd_hone(vl), vl);
    }

    // Find the first occurrence of maximum magnitude
    size_t result = 0;
    size_t remaining = n;
    size_t offset = 0;

