void cfar_ca_i32(const int32_t *p, uint8_t *det, size_t n, size_t guard, size_t train, int32_t alpha) {
    // Initialize output to zero
    for (size_t i = 0; i < n; i++) {
        det[i] = 0;
    }

    if (n < 2 * guard + 2 * train) return;

    // Vector processing
    size_t vl;
    const int32_t *p_ptr = p;
    uint8_t *det_ptr = det;

    // Process middle section with vector operations
    for (size_t i = guard + train; i < n - guard - train; i += vl) {
        vl = xd_slen(n - i - guard - train);

        // Load training cells before and after the cell
        xd_s s1, s2;
        xd_sload(p_ptr + i - guard - train, &s1, vl);
        xd_sload(p_ptr + i + guard + 1, &s2, vl);

        // Sum the training cells
        xd_s sum = xd_sadd(s1, s2, vl);
        int32_t s = xd_sredsum(sum, vl);

        // Load the cell to test
        xd_s cell;
        xd_sload(p_ptr + i, &cell, vl);

        // Compute: p[i] * (2*train) > alpha * S
        xd_s prod1 = xd_smul(cell, 2 * train, vl);
        xd_s prod2 = xd_smulx(s, alpha, vl);

        // Compare and store result
        xd_smask mask = xd_sgt(prod1, prod2, vl);
        xd_sstore_u8(det_ptr + i, mask, vl);
    }

    // Handle edge cases with scalar code
    for (size_t i = 0; i < guard + train; i++) {
        det[i] = 0;
    }
    for (size_t i = n - guard - train; i < n; i++) {
        det[i] = 0;
    }
