void fir_q15(const int16_t *x, const int16_t *h, int16_t *y, size_t n, size_t ntaps) {
    size_t vl;

    // Process output samples in chunks
    for (size_t i = 0; i < n; i += vl) {
        vl = xd_hlen(n - i);

        // Load filter coefficients into vector
        xd_h h_vec;
        xd_hload_iq(h, &h_vec, &h_vec, ntaps);

        // Initialize accumulator
        xd_w acc = xd_wzero(vl);

        // Compute FIR sum for this chunk
        size_t j;
        for (j = 0; j < ntaps; j += vl) {
            size_t tap_vl = xd_hlen(ntaps - j);

            // Load input samples
            xd_h x_vec;
            xd_hload_iq(&x[i + j], &x_vec, &x_vec, tap_vl);

            // Multiply and accumulate
            acc = xd_wmacx(acc, 1, x_vec, tap_vl);

            // Break if we've processed all taps
            if (j + tap_vl >= ntaps) break;
        }

        // Reduce accumulator to single value
        int32_t sum = xd_wredsum(acc, vl);

        // Convert Q30 result back to Q15 with rounding
        int32_t y_val = (sum + 16384) >> 15;
        y[i] = (int16_t)y_val;
    }
