#include "xdsp.h"

void decim2_q15(const int16_t *x, int16_t *y, size_t n) {
    size_t i;
    size_t vl;

    // Process pairs of input samples
    for (i = 0; i < n; i += vl) {
        vl = xd_hlen();
        if (i + vl > n) {
            vl = n - i;
        }

        // Load two consecutive samples for each output
        xd_h x0 = xd_hload(&x[2*i], vl);
        xd_h x1 = xd_hload(&x[2*i+1], vl);

        // Compute average: (x0 + x1 + 1) >> 1
        xd_h result = xd_havg(x0, x1, vl);

        // Store result
        xd_hstore(&y[i], result, vl);
    }
}

