void cfar_ca_i32(const int32_t *p, uint8_t *det, size_t n, size_t guard, size_t train, int32_t alpha) {
    if (n < 2 * guard + 2 * train) {
        for (size_t i = 0; i < n; ++i)
            det[i] = 0;
        return;
    }

    // Initialize detection array to zero
    for (size_t i = 0; i < n; ++i)
        det[i] = 0;

    size_t w = guard + train;

    // Process in chunks using XDSP vector operations
    for (size_t i = w; i < n - w; i += xd_hlen(n - i - w)) {
        size_t vl = xd_hlen(n - i - w);

        // Load training cells from left side
        xd_h left_train;
        xd_hload_iq(p + i - train - guard, &left_train, 0, vl);

        // Load training cells from right side
        xd_h right_train;
        xd_hload_iq(p + i + guard + 1, &right_train, 0, vl);

        // Compute sum of left training cells
        xd_w sum_left = xd_wzero(vl);
        for (size_t j = 0; j < train; ++j) {
            sum_left = xd_wmacx(sum_left, 1, left_train, vl);
            if (j + 1 < train) {
                // Shift right by one element
                left_train = xd_hshift_right(left_train, 1, vl);
            }
        }

        // Compute sum of right training cells
        xd_w sum_right = xd_wzero(vl);
        for (size_t j = 0; j < train; ++j) {
            sum_right = xd_wmacx(sum_right, 1, right_train, vl);
            if (j + 1 < train) {
                // Shift right by one element
                right_train = xd_hshift_right(right_train, 1, vl);
            }
        }

        // Combine sums
        xd_w sum = xd_wadd(sum_left, sum_right, vl);

        // Load current cell value
        xd_h current;
        xd_hload_iq(p + i, &current, 0, vl);

        // Compute threshold: alpha * S
        xd_w threshold = xd_wmacx(xd_wzero(vl), alpha, current, vl);
        threshold = xd_wadd(threshold, threshold, vl); // Multiply by 2

        // Compare p[i] * (2*train) > alpha * S
        xd_hmask mask = xd_wgtx(sum, threshold, vl);

        // Store results
        for (size_t j = 0; j < vl; ++j) {
            if (mask & (1 << j)) {
                det[i + j] = 1;
            }
        }
    }
}

