typedef struct { int16_t data[8]; } xd_h;
typedef struct { int32_t data[8]; } xd_w;
typedef struct { uint8_t data[8]; } xd_hmask;

size_t xd_hlen(size_t n) {
    return (n < 8) ? n : 8; // Assuming XD_HLANES = 8
}

void xd_hload_iq(const int16_t *p, xd_h *i_out, xd_h *q_out, size_t vl) {
    for (size_t i = 0; i < vl; ++i) {
        i_out->data[i] = p[2*i];
        q_out->data[i] = p[2*i+1];
    }
}

xd_w xd_wdup(int32_t x, size_t vl) {
    xd_w result;
    for (size_t i = 0; i < vl; ++i) {
        result.data[i] = x;
    }
    return result;
}

xd_w xd_wmacx(xd_w acc, int16_t k, xd_h a, size_t vl) {
    for (size_t i = 0; i < vl; ++i) {
        acc.data[i] += k * a.data[i];
    }
    return acc;
}

xd_h xd_hsra(xd_h a, unsigned sh, size_t vl) {
    xd_h result;
    for (size_t i = 0; i < vl; ++i) {
        result.data[i] = a.data[i] >> sh;
    }
    return result;
}

xd_w xd_wadd(xd_w a, xd_w b, size_t vl) {
    xd_w result;
    for (size_t i = 0; i < vl; ++i) {
        result.data[i] = a.data[i] + b.data[i];
    }
    return result;
}

xd_hmask xd_wgtx(xd_w a, int32_t x, size_t vl) {
    xd_hmask result;
    for (size_t i = 0; i < vl; ++i) {
        result.data[i] = (a.data[i] > x) ? 1 : 0;
    }
    return result;
}

void xd_wstore(int32_t *p, xd_w v, size_t vl) {
    for (size_t i = 0; i < vl; ++i) {
        p[i] = v.data[i];
    }
}

