        // Convert back to int16 with rounding
        xd_h result = xd_wnarrow(acc, 15, vl);
        xd_hstore(y + i, result, vl);

        // Reset accumulator for next iteration
        acc = xd_wdup(0, xd_hmaxlen());
    }
