void cmul_q15(const int16_t *a, const int16_t *b, int16_t *y, size_t n) {
    for (size_t vl; n > 0; n -= vl, a += vl * 2, b += vl * 2, y += vl * 2) {
        vl = xd_hlen(n);

        xd_h ai, ar, bi, br;
        xd_hload_iq(a, &ar, &ai, vl);
        xd_hload_iq(b, &br, &bi, vl);

        // Compute real part: re = ar*br - ai*bi
        xd_w re_acc = xd_wdup(0, xd_hmaxlen());
        re_acc = xd_wmac(re_acc, ar, br, vl);
        re_acc = xd_wmsb(re_acc, ai, bi, vl);

        // Compute imag part: im = ar*bi + ai*br
        xd_w im_acc = xd_wdup(0, xd_hmaxlen());
        im_acc = xd_wmac(im_acc, ar, bi, vl);
        im_acc = xd_wmac(im_acc, ai, br, vl);

        // Convert back to Q15 with rounding and saturation
        xd_h re = xd_wnarrow(re_acc, 15, vl);
        xd_h im = xd_wnarrow(im_acc, 15, vl);

        xd_hstore_iq(y, re, im, vl);
    }
}

