void fir_q15(const int16_t *x, const int16_t *h, int16_t *y, size_t n, size_t ntaps) {
    for (size_t i = 0; i < n; i++) {
        xd_w acc = xd_wdup(0, xd_hmaxlen());

        // Process all ntaps taps
        const int16_t *x_ptr = x + i;
        const int16_t *h_ptr = h;
        size_t remaining = ntaps;

        for (size_t vl; remaining > 0; remaining -= vl, x_ptr += vl, h_ptr += vl) {
            vl = xd_hlen(remaining);

            // Load filter coefficients
            xd_h vh = xd_hload(h_ptr, vl);

            // Load input samples  
            xd_h vx = xd_hload(x_ptr, vl);

            // Accumulate: acc += x[i+k] * h[k]
            acc = xd_wmac(acc, vx, vh, vl);
        }

        // Convert from Q30 to Q15 with rounding
        int32_t result = xd_wredsum(acc, xd_hmaxlen());
        int16_t y_val = (int16_t)((result + 16384) >> 15);

        y[i] = y_val;
    }
}

