        // Load and accumulate first training window
        for (size_t j = 0; j < train; j++) {
            size_t vl = xd_hlen(train - j);
            if (j + vl > train) vl = train - j;

            xd_h v1 = xd_hload(p + i - w + j, vl);
            acc = xd_wmac(acc, v1, v1, vl);
