float rms_f32(const float *x, size_t n) {
    if (n == 0) return 0.0f;

    xd_f acc = xd_fdup(0.0f, xd_slen(n));
    for (size_t vl; n > 0; n -= vl, x += vl) {
        vl = xd_slen(n);
        xd_f vx = xd_fload(x, vl);
        xd_f vxx = xd_fmac(vx, vx, vx, vl);  // vxx[i] = vx[i] * vx[i]
        acc = xd_fmacx(acc, 1.0f, vxx, vl);  // acc[i] += vxx[i]
    }

    float sum_sq = xd_fredsum(acc, xd_slen(1));  // Sum all lanes
    return sqrtf(sum_sq / (float)n);
}

